<?php
require dirname(__DIR__).'/app/bootstrap.php'; require_permission('taxonomy.manage'); ensure_taxonomy_schema();
$error=''; $notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $action=(string)($_POST['action']??''); $name=trim((string)($_POST['name']??''));
 try {
  if($action==='create_category'){
   $desc=trim((string)($_POST['description']??''));
   if($name===''||text_length($name)>120) throw new RuntimeException('Nama kategori wajib diisi (maksimal 120 karakter).');
   if(text_length($desc)>500) throw new RuntimeException('Deskripsi maksimal 500 karakter.');
   $q=$pdo->prepare('INSERT INTO categories(name,slug,description) VALUES(?,?,?)'); $q->execute([$name,slugify($name),$desc?:null]); $notice='Kategori berhasil dibuat.'; cache_clear();
  } elseif($action==='create_tag'){
   if($name===''||text_length($name)>80) throw new RuntimeException('Nama tag wajib diisi (maksimal 80 karakter).');
   $q=$pdo->prepare('INSERT INTO tags(name,slug) VALUES(?,?)'); $q->execute([$name,slugify($name)]); $notice='Tag berhasil dibuat.'; cache_clear();
  } elseif($action==='delete_category'){
   $pdo->prepare('DELETE FROM categories WHERE id=?')->execute([(int)($_POST['id']??0)]); $notice='Kategori dihapus. Artikel tetap ada.'; cache_clear();
  } elseif($action==='delete_tag'){
   $pdo->prepare('DELETE FROM tags WHERE id=?')->execute([(int)($_POST['id']??0)]); $notice='Tag dihapus. Artikel tetap ada.'; cache_clear();
  }
 } catch(Throwable $ex){ $error=$ex instanceof RuntimeException?$ex->getMessage():((($ex instanceof PDOException)&&(($ex->errorInfo[1]??null)===1062))?'Nama/slug sudah ada. Gunakan nama lain.':'Perubahan gagal disimpan. Periksa log server.'); if(!($ex instanceof RuntimeException)) error_log('NOWRD taxonomy error: '.$ex->getMessage()); }
}
$categories=$pdo->query('SELECT c.*, (SELECT COUNT(*) FROM post_categories pc WHERE pc.category_id=c.id) post_count FROM categories c ORDER BY c.name')->fetchAll();
$tags=$pdo->query('SELECT t.*, (SELECT COUNT(*) FROM post_tags pt WHERE pt.tag_id=t.id) post_count FROM tags t ORDER BY t.name')->fetchAll();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Categories & Tags — NOWRD</title><link rel="stylesheet" href="<?=e(base_url('public/assets/style.css'))?>"><style>.tax-wrap{max-width:1100px;margin:0 auto;padding:34px 24px}.tax-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.tax-card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:22px;min-width:0}.tax-form{display:grid;gap:10px;margin:18px 0 24px}.tax-form input,.tax-form textarea{width:100%;border:1px solid var(--line);border-radius:10px;padding:11px;font:inherit}.tax-item{display:flex;align-items:center;gap:10px;padding:12px 0;border-top:1px solid var(--line)}.tax-item .meta{flex:1;min-width:0}.tax-item small{display:block;color:var(--muted);overflow-wrap:anywhere}.tax-item form{margin:0}.danger-mini{border:1px solid #f1d5d1;color:#a33;background:#fff8f7;border-radius:8px;padding:7px 9px;cursor:pointer}.tax-count{font-size:12px;color:var(--muted)}@media(max-width:700px){.tax-wrap{padding:22px 14px}.tax-grid{grid-template-columns:1fr}}</style></head><body class="dashboard"><aside class="sidebar"><a class="brand" href="<?=e(base_url('index.php'))?>"><span class="brand-mark"><?=e(setting('brand_mark','n.'))?></span> <?=e(setting('brand_name','NOWRD'))?></a><div class="side-label">WORKSPACE</div><a class="side-link" href="<?=e(base_url('admin/index.php'))?>">▦ &nbsp; Overview</a><a class="side-link" href="<?=e(base_url('admin/post.php'))?>">✎ &nbsp; New story</a><a class="side-link" href="<?=e(base_url('admin/media.php'))?>">▧ &nbsp; Media Library</a><a class="side-link active" href="<?=e(base_url('admin/taxonomies.php'))?>">◇ &nbsp; Categories & Tags</a><a class="side-link" href="<?=e(base_url('admin/settings.php'))?>">⚙ &nbsp; Settings</a><a class="side-link" href="<?=e(base_url('admin/users.php'))?>">♙ &nbsp; Admin accounts</a><a class="side-link" href="<?=e(base_url('admin/maintenance.php'))?>">⌁ &nbsp; Maintenance</a><a class="side-link" href="<?=e(base_url('index.php'))?>">↗ &nbsp; View website</a></aside><main class="admin-main"><div class="tax-wrap"><header class="admin-top"><div><div class="eyebrow">CONTENT ORGANIZATION</div><h1>Categories & tags<span class="lime">.</span></h1><p class="muted">Keep your journal organized without slowing down your writing.</p></div><a class="button" href="<?=e(base_url('admin/post.php'))?>">＋ New story</a></header><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="success"><?=e($notice)?></div><?php endif;?><div class="tax-grid"><section class="tax-card"><div class="eyebrow">BROAD TOPICS</div><h2>Categories</h2><form method="post" class="tax-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create_category"><label for="catName">Category name</label><input id="catName" name="name" maxlength="120" required placeholder="e.g. Essays"><label for="catDesc">Description (optional)</label><textarea id="catDesc" name="description" maxlength="500" rows="2" placeholder="What belongs in this category?"></textarea><button class="button" type="submit">Create category</button></form><?php if(!$categories):?><p class="muted">No categories yet.</p><?php endif;?><?php foreach($categories as $c):?><div class="tax-item"><div class="meta"><b><?=e($c['name'])?></b><small>/<?=e($c['slug'])?> · <?= (int)$c['post_count']?> stories</small></div><form method="post" data-confirm-message="Delete category? Stories will remain."><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_category"><input type="hidden" name="id" value="<?= (int)$c['id']?>"><button class="danger-mini" type="submit">Delete</button></form></div><?php endforeach;?></section><section class="tax-card"><div class="eyebrow">SPECIFIC KEYWORDS</div><h2>Tags</h2><form method="post" class="tax-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create_tag"><label for="tagName">Tag name</label><input id="tagName" name="name" maxlength="80" required placeholder="e.g. Notes"><button class="button" type="submit">Create tag</button></form><?php if(!$tags):?><p class="muted">No tags yet. You can also create tags from the article editor.</p><?php endif;?><?php foreach($tags as $t):?><div class="tax-item"><div class="meta"><b><?=e($t['name'])?></b><small>/<?=e($t['slug'])?> · <?= (int)$t['post_count']?> stories</small></div><form method="post" data-confirm-message="Delete tag? Stories will remain."><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_tag"><input type="hidden" name="id" value="<?= (int)$t['id']?>"><button class="danger-mini" type="submit">Delete</button></form></div><?php endforeach;?></section></div></div></main><script>const nowrdConfirmDelete = <?=json_encode(setting('confirm_delete','1')==='1')?>;if(nowrdConfirmDelete){document.querySelectorAll('form[data-confirm-message]').forEach(form=>form.addEventListener('submit',event=>{if(!confirm(form.dataset.confirmMessage||'Continue?'))event.preventDefault()}))}</script><script>window.NOWRD_VISUAL = <?=json_encode(nowrd_visual_preferences(), JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>; window.NOWRD_VISUAL_ADMIN = true; window.NOWRD_CSRF = <?=json_encode(csrf_token())?>; window.NOWRD_VISUAL_SAVE_URL = <?=json_encode(base_url('admin/visual-settings.php'))?>;</script><script src="<?=e(base_url('public/assets/ui-v10.js'))?>" defer></script>
</body></html>